function buildActivityEvidence(
  history: ChatMessage[],
  todayMemory: MisakiTodayMemory
): ActivityEvidence {
  return {
    texts: [
      ...history
        .filter(
          (item) =>
            item.role === "misaki"
        )
        .slice(-20)
        .map(
          (item) => item.text
        ),
      ...todayMemory.items,
    ],
  };
}

const activityGroups = [
  {
    name: "買い物",
    patterns: [
      "買い物",
      "スーパー",
      "コンビニ",
    ],
  },
  {
    name: "外出",
    patterns: [
      "出かけ",
